 public function testApprovedPhotoIsEmbeddedFromProtectedBytesAndDriftBlocksReconstruction(string $engine):void {
  $input=$this->deterministicFixture($engine);$p=$this->image();file_put_contents($p,DigiForge\POD\RasterArtworkCodec::encode(2,2,"\xff\0\0\xff\0\0\xff\xff\0\xff\0\xff\0\0\0\xff"));$v=new DigiForge\POD\RenderArtifactVerifier();$stored=(new DigiForge\POD\RenderArtifactStore())->retain($p,$v->readArtifact($p));self::assertNotWPError($stored);$path=DigiForge\ProductFactory\AssetStorage::absolutePath($stored['storage_reference']);$original=(string)file_get_contents($path);global $wpdb;$payload=DigiForge\Orders\Validator::canonicalJson(['name'=>'Ada','photo'=>$stored['storage_reference']]);$wpdb->update(DigiForge\Database\Tables::personalization_submissions(),['canonical_payload'=>$payload,'payload_hash'=>hash('sha256',$payload)],['payload_hash'=>$input['personalization_evidence_hash']]);$input['personalization_evidence_hash']=hash('sha256',$payload);$recipe=$this->recipe();$recipe['engine']=$engine;$recipe['slots'][]=['type'=>'image','field'=>'photo','x'=>10,'y'=>150,'width'=>100,'height'=>100];$renderer=new DigiForge\POD\DeterministicPersonalizationRenderer();try{self::assertNotWPError($renderer->approveRecipe($input['template_key'],1,$recipe));$expected=$renderer->expected($input);self::assertNotWPError($expected);self::assertStringContainsString('data:image/png;base64,'.base64_encode($original),$expected['svg']);
  $raster=DigiForge\POD\LocalArtworkAdapter::convert($expected['svg'],'png');self::assertNotWPError($raster);$decoded=DigiForge\POD\RasterArtworkCodec::decode($raster['bytes']);self::assertSame("\xff\0\0\xff",substr($decoded['rgba'],(160*640+20)*4,4));self::assertSame("\0\0\xff\xff",substr($decoded['rgba'],(160*640+90)*4,4));self::assertSame("\0\xff\0\xff",substr($decoded['rgba'],(230*640+20)*4,4));self::assertSame("\0\0\0\xff",substr($decoded['rgba'],(230*640+90)*4,4));
  file_put_contents($path,'not an image');self::assertWPError($renderer->expected($input));}finally{file_put_contents($path,$original);unlink($p);}
 }
