  $input=$this->deterministicFixture('NAME_MONOGRAM',[['position'=>'front','decoration_method'=>'dtg','width_px'=>640,'height_px'=>480],['position'=>'back','decoration_method'=>'dtg','width_px'=>640,'height_px'=>480]]);$renderer=new DigiForge\POD\DeterministicPersonalizationRenderer();$recipe=['engine'=>'NAME_MONOGRAM','background'=>'#ffffff','bitmap_font'=>$this->recipe()['bitmap_font'],'panels'=>['front'=>['slots'=>$this->recipe()['slots']],'back'=>['slots'=>$this->recipe()['slots']]]];self::assertNotWPError($renderer->approveRecipe($input['template_key'],1,$recipe));$front=tempnam(sys_get_temp_dir(),'df-front-');$back=tempnam(sys_get_temp_dir(),'df-back-');try{file_put_contents($front,$renderer->expected($input,'front')['svg']);file_put_contents($back,$renderer->expected($input,'back')['svg']);$repo=new DigiForge\POD\RenderEvidenceRepository();self::assertWPError($repo->createFromPanelArtifacts($input,['front'=>$front],['front'=>$front]));$r=$repo->createFromPanelArtifacts($input,['front'=>$front,'back'=>$back],['front'=>$front,'back'=>$back]);self::assertNotWPError($r);self::assertSame('APPROVED',$repo->approve((int)$r['id'])['review_status']);$wf=new DigiForge\POD\DeterministicRenderWorkflow();$preview=$wf->preview((int)$r['id'],'back');self::assertSame(['back','front'],$preview['available_panels']);$_GET['df_render_id']=$r['id'];$_GET['df_render_panel']='back';try{ob_start();$wf->render('personalized_pod');$html=ob_get_clean();self::assertStringContainsString('aria-label="Certified preview panels"',$html);self::assertStringContainsString('df_render_panel=front',$html);self::assertStringContainsString('aria-current="true"',$html);$directory=getenv('DF_PORTAL_FIXTURE_DIR');if(is_string($directory)&&$directory!==''){$_GET['df_view']='pod_personalized';$_GET['df_shop']='personalized_pod';$portal=(new DigiForge\Portal\Portal())->render();self::assertStringContainsString('Inspect stored artifacts',$portal);self::assertSame(strlen($portal),file_put_contents($directory.'/portal-pod_personalized--personalized_pod.html',$portal));}}finally{unset($_GET['df_render_id'],$_GET['df_render_panel']);}}finally{unlink($front);unlink($back);}
 }
