 /** @dataProvider repeatEngines */
 public function testApprovedRepeatEngineReproducesActualRasterAndPdfPanels(string $engine):void {
  $input=$this->deterministicFixture($engine,[['position'=>'front','decoration_method'=>'aop','width_px'=>12,'height_px'=>8,'dpi'=>300,'qa_geometry'=>['safe_zone'=>['x'=>1,'y'=>1,'width'=>10,'height'=>6],'seam_exclusions'=>[],'min_image_dpi'=>300]]]);
  $source=tempnam(sys_get_temp_dir(),'df-repeat-source-');$output=tempnam(sys_get_temp_dir(),'df-repeat-output-');
  try{
   file_put_contents($source,DigiForge\POD\RasterArtworkCodec::encode(2,2,str_repeat("\xff\0\0\xff",4)));
   $stored=(new DigiForge\POD\RenderArtifactStore())->retain($source,(new DigiForge\POD\RenderArtifactVerifier())->readArtifact($source));self::assertNotWPError($stored);
   global $wpdb;$payload=DigiForge\Orders\Validator::canonicalJson(['photo'=>$stored['storage_reference']]);$wpdb->update(DigiForge\Database\Tables::personalization_submissions(),['canonical_payload'=>$payload,'payload_hash'=>hash('sha256',$payload)],['payload_hash'=>$input['personalization_evidence_hash']]);$input['personalization_evidence_hash']=hash('sha256',$payload);
   $recipe=['engine'=>$engine,'background'=>'#ffffff','slots'=>[['type'=>'image','field'=>'photo','x'=>1,'y'=>1,'width'=>2,'height'=>2,'repeat'=>['columns'=>3,'rows'=>2,'gap_x'=>1,'gap_y'=>1]]]];
   $renderer=new DigiForge\POD\DeterministicPersonalizationRenderer();self::assertNotWPError($renderer->approveRecipe($input['template_key'],1,$recipe));$expected=$renderer->expected($input);self::assertNotWPError($expected);self::assertSame(6,substr_count($expected['svg'],'<image '));self::assertSame('VERIFIED_LOCAL_GEOMETRY',$expected['geometry_qa']['state']);self::assertFalse($expected['geometry_qa']['supplier_certified']);
   foreach(['png','pdf']as $format){$actual=DigiForge\POD\LocalArtworkAdapter::convert($expected['svg'],$format,300);self::assertNotWPError($actual);file_put_contents($output,$actual['bytes']);$record=(new DigiForge\POD\RenderEvidenceRepository())->createFromArtifacts($input,$output,$output);self::assertNotWPError($record);$proof=(new DigiForge\POD\RenderArtifactVerifier())->assertCertified($record);self::assertNotWPError($proof);self::assertTrue($proof['deterministic_personalization_verified']);$preview=(new DigiForge\POD\DeterministicRenderWorkflow())->preview((int)$record['id'],'front');self::assertNotWPError($preview);self::assertArrayHasKey('geometry_qa',$preview);self::assertSame('VERIFIED_LOCAL_GEOMETRY',$preview['geometry_qa']['state']);self::assertFalse($preview['geometry_qa']['supplier_certified']);}
   $png=DigiForge\POD\RasterArtworkCodec::decode(DigiForge\POD\LocalArtworkAdapter::convert($expected['svg'],'png')['bytes']);self::assertSame("\xff\0\0\xff",substr($png['rgba'],(4*12+7)*4,4));self::assertSame("\xff\xff\xff\xff",substr($png['rgba'],(3*12+7)*4,4));
   $path=DigiForge\ProductFactory\AssetStorage::absolutePath($stored['storage_reference']);$original=file_get_contents($path);try{file_put_contents($path,'drift');self::assertWPError($renderer->expected($input));}finally{file_put_contents($path,$original);}
  }finally{unlink($source);unlink($output);}
 }
